__NUXT_JSONP__("/jp/how-to-apply/visa_overseas", (function(a){return {data:[{details:{slug:"jp",pageTitle:"海外からの長期留学申込 | Mentor Language Institute",pageDescription:a,title:"海外からの長期留学申込",image:"\u002Fimages\u002Fvisa-overseas\u002Fvisa.jpg",category:[{title:a,list_content:["アメリカ国外（日本）に滞在している","アメリカに90日以上滞在する予定","アメリカ国内の語学学校（教育機関）に通われる方"]},{title:"手続きの手順",image:"\u002Fimages\u002Fvisa-overseas\u002Fsteps-jp.jpg",ordered_content:["お申し込み","必要書類の提出","I-20の受領","Visa申請\u002F面接","渡米"],content:["学生ビザを取得して留学する場合、\u003Cspan class='ymarker'\u003E通常3ヵ月程度の準備期間\u003C\u002Fspan\u003Eを要します。\u003Cbr \u002F\u003E余裕を持った手続きを進めるために\u003Cspan class='hutoaka'\u003E遅くとも3ヶ月前にはお申込み\u003C\u002Fspan\u003Eをお願いします。\u003Cbr \u002F\u003E3ヵ月を切りお申込みをする際は、その旨スタッフまでお申し出ください。"]},{title:"お申し込み後の手続きの進め方について",image:"\u002Fimages\u002Fvisa-overseas\u002Fmli-short-jp.jpg",content:["お申し込み後はiMLIと言う当校独自の申し込みシステムにより手続きを進めて参ります。\u003Cbr \u002F\u003E手続き方法はiMLIに記載され、ひとつひとつ順を追って進めていく事が可能です。"]},{title:"お申込みはこちら",content:["米国ビザに関する情報の入力\u003Cbr \u002F\u003E手続きに関する質問のやりとりも","以下、フォームボタンよりお申込みください。"]}],btn_label:"オンライン申込フォームへ",admission:{link:"\u002Fjp\u002Fadmission",content:["※お申込みの際はクレジットカードをご用意ください。"]},dir:"\u002Fvisa-overseas",path:"\u002Fvisa-overseas\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:31.335Z",updatedAt:"2025-05-26T12:06:28.030Z"}}],fetch:{},mutations:void 0}}("学生ビザを申請する方")));